from accounting import gl_codes


def add_owner_funding_accounts(apps, schema_editor):
    """
    Add 2500 Loan from Shareholder and the 6110-6130 expense accounts, each
    expense account with its category. Idempotent: an account whose code
    already exists (added in admin, say) is left as it is, and so is a
    category of the same name, except that one without a GL account gets it.
    """
    ChartOfAccount = apps.get_model("accounting", "ChartOfAccount")
    ExpenseCategory = apps.get_model("billing", "ExpenseCategory")
    for code, name, kind, category_name in gl_codes.OWNER_FUNDING_ACCOUNTS:
        account, _ = ChartOfAccount.objects.get_or_create(
            code=code, defaults={"name": name, "type": kind, "is_active": True}
        )
        if category_name is None:
            continue
        category, created = ExpenseCategory.objects.get_or_create(
            name=category_name, defaults={"account": account, "billable_by_default": False}
        )
        if not created and category.account_id is None:
            category.account = account
            category.save(update_fields=["account"])


